SELECT CASE WHEN budget >= 4241000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, PERCENTILE_APPROX(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, SUM(CASE WHEN dept_name = 'Sales' THEN budget ELSE 0 END) AS sales_budget, COUNT(*) FILTER (WHERE location = 'Singapore') AS singapore_rows, ROUND(AVG(budget), 2) AS avg_budget FROM departments GROUP BY CASE WHEN budget >= 4241000 THEN 'PREMIUM' ELSE 'STANDARD' END;
